def main():
    assert len(TOPICS) == 60, len(TOPICS)
    rows = []
    for topic, answer, keywords in TOPICS:
        for kw in keywords:
            assert kw.lower() in answer.lower(), f"keyword {kw!r} missing from answer on {topic!r}"
        for template in Q_TEMPLATES:
            rows.append({
                "messages": [
                    {"role": "system", "content": SYSTEM},
                    {"role": "user", "content": template.format(t=topic)},
                    {"role": "assistant", "content": answer},
                ],
                "eval_keywords": keywords,
            })
    assert len(rows) == 300, len(rows)
    OUT.parent.mkdir(parents=True, exist_ok=True)
    with open(OUT, "w") as fh:
        for row in rows:
            fh.write(json.dumps(row) + "\n")
    print(f"wrote {len(rows)} rows to {OUT}")


if __name__ == "__main__":
    main()
